// Parses the repo's real action.yml into src/data/action-schema.generated.json so
// /configuration and the Workflow Generator can never drift from the 26 real inputs -
// this file is gitignored and gets regenerated by the `predev`/`prebuild` npm scripts on
// every single run, never hand-edited.
import { parse } from 'yaml';
import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import path from 'node:path';

const websiteRoot = path.dirname(path.dirname(fileURLToPath(import.meta.url)));
const actionYmlPath = path.join(websiteRoot, '..', 'action.yml');
const outPath = path.join(websiteRoot, 'src', 'data', 'action-schema.generated.json');

const raw = readFileSync(actionYmlPath, 'utf-8');
const doc = parse(raw);

const inputs = Object.entries(doc.inputs ?? {}).map(([name, def]) => ({
  name,
  description: def.description ?? '',
  required: def.required === true,
  default: def.default ?? null,
}));

const outputs = Object.entries(doc.outputs ?? {}).map(([name, def]) => ({
  name,
  description: def.description ?? '',
}));

mkdirSync(path.dirname(outPath), { recursive: true });
writeFileSync(outPath, JSON.stringify({ inputs, outputs }, null, 2) + '\n', 'utf-8');

console.log(`generate-action-schema: wrote ${inputs.length} inputs, ${outputs.length} outputs -> ${path.relative(websiteRoot, outPath)}`);
